var samples = new[] {
    new LabEvidence("A", true, true, false, true),
    new LabEvidence("B", true, false, true, true)
};
foreach (var item in samples)
{
    string next = item.CaptureFrames ? "sender attachment or RTP path" : "device or capture path";
    Console.WriteLine($"{item.Id}: active={item.Active} capture={item.CaptureFrames} attached={item.Attached} rx={item.Rx} next={next}");
}
// A: capture=True attached=False；B: capture=False attached=True
// Lab bool是虛構輸入，不是Ozeki提供的遙測API。

var line = new LabLine("L1");
var c1 = new LabCall("C1", line);
var c2 = new LabCall("C2", line);
using var s1 = new LabSession(c1);
using var s2 = new LabSession(c2);
c1.Emit(LabCallState.Active);
c2.Emit(LabCallState.Active);
c1.HangUp();
Console.WriteLine(s1.Ended); // True
Console.WriteLine(s2.Media.Tx("C2")); // True
Console.WriteLine(s2.Media.Rx("C2")); // True
c2.HangUp();
Console.WriteLine(c2.HandlerCount); // 0
